226→/// An option in a select prompt.
227→#[derive(Debug, Clone)]
228→pub struct PromptOption {
229→    /// Display label.
230→    pub label: String,
231→    /// Value returned when selected.
232→    pub value: String,
233→}
234→
235→/// Result of a prompt.
236→#[derive(Debug, Clone)]
237→pub enum PromptResult {
238→    /// Boolean result from confirm.
239→    Bool(bool),
240→    /// String result from input or select.
241→    String(String),
