  1→//! Lint diagnostic messages.
  2→//!
  3→//! This module provides the [`LintDiagnostic`] type for representing
  4→//! issues found during configuration validation, with optional source
  5→//! location tracking for precise error reporting.
  6→
  7→use super::rule::{RuleId, Severity};
  8→use super::span::Span;
  9→
 10→/// A diagnostic message produced by a lint rule.
 11→#[derive(Debug, Clone)]
 12→pub struct LintDiagnostic {
 13→    /// The rule that produced this diagnostic.
 14→    pub rule_id: RuleId,
 15→    /// Severity of this diagnostic.
 16→    pub severity: Severity,
 17→    /// Human-readable message.
 18→    pub message: String,
 19→    /// Optional source location.
 20→    pub span: Option<Span>,
 21→    /// Optional suggestion for fixing the issue.
 22→    pub suggestion: Option<String>,
 23→    /// Additional related locations.
 24→    pub related: Vec<RelatedInfo>,
 25→}
 26→
 27→/// Additional information related to a diagnostic.
 28→#[derive(Debug, Clone)]
 29→pub struct RelatedInfo {
 30→    /// Location of the related information.
 31→    pub span: Span,
 32→    /// Message explaining the relationship.
 33→    pub message: String,
 34→}
 35→
 36→impl LintDiagnostic {
 37→    /// Create a new diagnostic.
 38→    pub fn new(rule_id: RuleId, severity: Severity, message: impl Into<String>) -> Self {
 39→        Self {
 40→            rule_id,
 41→            severity,
 42→            message: message.into(),
 43→            span: None,
 44→            suggestion: None,
 45→            related: vec![],
 46→        }
 47→    }
 48→
 49→    /// Add a source span to this diagnostic.
 50→    pub fn with_span(mut self, span: Span) -> Self {
 51→        self.span = Some(span);
 52→        self
 53→    }
 54→
 55→    /// Add a fix suggestion.
 56→    pub fn with_suggestion(mut self, suggestion: impl Into<String>) -> Self {
 57→        self.suggestion = Some(suggestion.into());
 58→        self
 59→    }
 60→
 61→    /// Add related information.
 62→    pub fn with_related(mut self, span: Span, message: impl Into<String>) -> Self {
 63→        self.related.push(RelatedInfo {
 64→            span,
 65→            message: message.into(),
 66→        });
 67→        self
 68→    }
 69→}
 70→
 71→#[cfg(test)]
 72→mod tests {
 73→    use super::*;
 74→
 75→    #[test]
 76→    fn diagnostic_creation() {
 77→        let diag = LintDiagnostic::new(RuleId::new("test-rule"), Severity::Error, "Test message");
 78→
 79→        assert_eq!(diag.rule_id, RuleId::new("test-rule"));
 80→        assert_eq!(diag.severity, Severity::Error);
 81→        assert_eq!(diag.message, "Test message");
 82→        assert!(diag.suggestion.is_none());
 83→        assert!(diag.span.is_none());
 84→        assert!(diag.related.is_empty());
 85→    }
 86→
 87→    #[test]
 88→    fn diagnostic_with_suggestion() {
 89→        let diag = LintDiagnostic::new(RuleId::new("test-rule"), Severity::Warning, "Test warning")
 90→            .with_suggestion("Fix it like this");
 91→
 92→        assert!(diag.suggestion.is_some());
 93→        assert_eq!(diag.suggestion.unwrap(), "Fix it like this");
 94→    }
 95→
 96→    #[test]
 97→    fn diagnostic_builder_pattern() {
 98→        let diag = LintDiagnostic::new(RuleId::new("test"), Severity::Error, "Test message")
 99→            .with_span(Span::line("config.yml", 10))
100→            .with_suggestion("Fix it like this");
101→
102→        assert_eq!(diag.message, "Test message");
103→        assert!(diag.span.is_some());
104→        assert!(diag.suggestion.is_some());
105→    }
106→
107→    #[test]
108→    fn diagnostic_with_related_info() {
109→        let diag = LintDiagnostic::new(
110→            RuleId::new("circular-dependency"),
111→            Severity::Error,
112→            "Circular dependency detected",
113→        )
114→        .with_related(Span::line("config.yml", 5), "step_a defined here")
115→        .with_related(Span::line("config.yml", 10), "step_b depends on step_a");
116→
117→        assert_eq!(diag.related.len(), 2);
118→        assert_eq!(diag.related[0].message, "step_a defined here");
119→        assert_eq!(diag.related[1].message, "step_b depends on step_a");
120→    }
