//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands (`::error::`,
//! `::warning::`, `::notice::`) so CI runners surface annotations inline on
//! pull-request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic becomes a `::error::`, `::warning::`, or `::notice::`
/// annotation. File, line, and column metadata are included when available
/// so GitHub can pin the annotation to the correct source location.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn command_for(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }

    /// Escape characters that have special meaning inside workflow command
    /// message values (`%`, `\r`, `\n`).
    fn escape_message(msg: &str) -> String {
        msg.replace('%', "%25")
            .replace('\r', "%0D")
            .replace('\n', "%0A")
    }

    /// Escape characters that have special meaning inside workflow command
    /// property values (`,`, `:` in addition to the message escapes).
    fn escape_property(value: &str) -> String {
        Self::escape_message(value)
            .replace(',', "%2C")
            .replace(':', "%3A")
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let cmd = Self::command_for(diag.severity);

            // Build the properties portion: file, line, col, title
            let mut props = Vec::new();

            if let Some(ref span) = diag.span {
                props.push(format!(
                    "file={}",
                    Self::escape_property(&span.file.display().to_string())
                ));
                props.push(format!("line={}", span.start_line));
                if span.start_col > 1 {
                    props.push(format!("col={}", span.start_col));
                }
                if span.end_line > span.start_line {
                    props.push(format!("endLine={}", span.end_line));
                }
                if span.end_col > span.start_col || span.end_line > span.start_line {
                    props.push(format!("endColumn={}", span.end_col));
                }
            }

            props.push(format!("title={}", Self::escape_property(&diag.rule_id.0)));

            let props_str = props.join(",");

            let mut message = Self::escape_message(&diag.message);

            if let Some(ref suggestion) = diag.suggestion {
                message.push_str("%0A");
                message.push_str(&Self::escape_message(&format!("help: {suggestion}")));
            }

            writeln!(writer, "::{cmd} {props_str}::{message}")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    fn format_output(diagnostics: &[LintDiagnostic]) -> String {
        let formatter = GithubActionsFormatter::new();
        let mut output = Vec::new();
        formatter.format(diagnostics, &mut output).unwrap();
        String::from_utf8(output).unwrap()
    }

    #[test]
    fn emits_error_annotation() {
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something is wrong",
        )];
        let output = format_output(&diagnostics);

        assert!(output.starts_with("::error "));
        assert!(output.contains("title=test-rule"));
        assert!(output.contains("::Something is wrong"));
    }

    #[test]
    fn emits_warning_annotation() {
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("warn-rule"),
            Severity::Warning,
            "Heads up",
        )];
        let output = format_output(&diagnostics);

        assert!(output.starts_with("::warning "));
    }

    #[test]
    fn emits_notice_for_hints() {
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("hint-rule"),
            Severity::Hint,
            "FYI",
        )];
        let output = format_output(&diagnostics);

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_file_and_line() {
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("loc-rule"), Severity::Error, "bad")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];
        let output = format_output(&diagnostics);

        assert!(output.contains("file=config.yml"));
        assert!(output.contains("line=10"));
        assert!(output.contains("col=5"));
    }

    #[test]
    fn omits_file_when_no_span() {
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("no-loc"),
            Severity::Error,
            "no location",
        )];
        let output = format_output(&diagnostics);

        assert!(!output.contains("file="));
        assert!(!output.contains("line="));
    }

    #[test]
    fn includes_suggestion_in_message() {
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("fix-rule"), Severity::Warning, "issue found")
                    .with_suggestion("Try this instead"),
            ];
        let output = format_output(&diagnostics);

        assert!(output.contains("issue found"));
        assert!(output.contains("help: Try this instead"));
    }

    #[test]
    fn escapes_special_characters_in_message() {
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("esc-rule"),
            Severity::Error,
            "line1\nline2\rline3%done",
        )];
        let output = format_output(&diagnostics);

        assert!(output.contains("line1%0Aline2%0Dline3%25done"));
    }

    #[test]
    fn escapes_special_characters_in_properties() {
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("path:rule"), Severity::Error, "msg")
                    .with_span(Span::new("dir,name/config.yml", 1, 1, 1, 1)),
            ];
        let output = format_output(&diagnostics);

        assert!(output.contains("file=dir%2Cname/config.yml"));
        assert!(output.contains("title=path%3Arule"));
    }

    #[test]
    fn handles_empty_diagnostics() {
        let output = format_output(&[]);
        assert!(output.is_empty());
    }

    #[test]
    fn multiple_diagnostics_produce_multiple_lines() {
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "err1"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warn1"),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Hint, "hint1"),
        ];
        let output = format_output(&diagnostics);
        let lines: Vec<&str> = output.lines().collect();

        assert_eq!(lines.len(), 3);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
        assert!(lines[2].starts_with("::notice "));
    }

    #[test]
    fn default_impl_works() {
        let formatter = GithubActionsFormatter::default();
        let diagnostics: Vec<LintDiagnostic> = vec![];
        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        assert!(output.is_empty());
    }

    #[test]
    fn includes_end_line_for_multiline_span() {
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("multi"), Severity::Error, "spans lines")
                    .with_span(Span::new("config.yml", 5, 1, 10, 20)),
            ];
        let output = format_output(&diagnostics);

        assert!(output.contains("line=5"));
        assert!(output.contains("endLine=10"));
        assert!(output.contains("endColumn=20"));
    }
}
